import { CacheDataLastTime } from 'domain/model/background'
import { CompanyApiResponse } from 'domain/model/company'
import { FETCH_ALL_TRACKABLE_STORE_TIME, getTimeWithNow } from 'shared/cache'
import { getItemFromCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'
import { handleRequest } from 'utils/handleRequest'

export async function getAllStores() {
  const storeCached = await getItemFromCache<
    CacheDataLastTime<CompanyApiResponse[]>
  >('stores')

  if (storeCached?.data && !isDateExpired(storeCached?.lastFetch)) {
    console.info(
      '[RA+] Got trackable store from cache expiring in ',
      new Date(storeCached?.lastFetch).toISOString()
    )
    return
  }

  return await fetchAllStores()
}

async function fetchAllStores() {
  try {
    const data = await handleRequest<CompanyApiResponse[]>({
      url: `/v1/company/summary`,
      headers: { 'Accept-Encoding': 'gzip' },
    })

    const storesWithLastFetch: CacheDataLastTime<CompanyApiResponse[]> = {
      lastFetch: getTimeWithNow(FETCH_ALL_TRACKABLE_STORE_TIME),
      data: data,
    }
    chrome.storage.local.set({ stores: JSON.stringify(storesWithLastFetch) })
  } catch (err) {
    console.error(err)
  }
}
