import { Tab } from 'domain/model/tab'
import { isValidStoreBackground } from './store/valid-store-background'
import { setChromeLocalData } from 'hooks/chrome-storage-change-data'
import { fetchCompanyDiscounts } from './fetch-company-discounts/main'
import { CURRENT_COMPANY_DISCOUNTS } from 'shared/caches/company-discounts'

export async function handleBackgroundApi(currentTab: Tab): Promise<void> {
  const { store, isValid, shortname, shortSubdomainExtracted, isRAPage } =
    await isValidStoreBackground()

  if (currentTab?.url) {
    const currentTabIsTheSameDomain = currentTab?.url?.includes(
      shortSubdomainExtracted
    )

    if (!currentTabIsTheSameDomain) return
  }

  if (!isValid) {
    return setChromeLocalData({
      [CURRENT_COMPANY_DISCOUNTS]: null,
    })
  }

  await fetchCompanyDiscounts({ store, isRAPage, shortname })
}
