import { getRavConfig } from 'domain/services/rav-config'

export const ravConfigListenerTypes = {
  getRavConfig: 'GET_RAV_CONFIG',
}

interface Message {
  type: string
  data: any
}
export const ravConfigListenerListener =
  (port: chrome.runtime.Port) => async (msg: Message) => {
    let data

    if (msg.type === ravConfigListenerTypes.getRavConfig) {
      data = await getRavConfig()
    }

    if (!data)
      data = { status: 400, message: 'Invalid Rav Config Listener Type' }

    return port.postMessage(data)
  }
