import { backgroundApiRequest } from './background-api-request'

type OnActivatedListener = (activeInfo: chrome.tabs.TabActiveInfo) => void
export const onActivatedListener: OnActivatedListener = (event) => {
  if (event?.tabId)
    backgroundApiRequest({
      currentTab: { id: event.tabId },
      errorOrigin: 'onActivated',
    })

  return true
}
