import { isEmpty } from 'utils/isEmpty'
import { Tab } from 'domain/model/tab'

interface TabFocusChangedProps {
  currentWindowId: number
  callback?: (currentTab: Tab) => void
}

export function tabFocusChanged({
  currentWindowId,
  callback,
}: TabFocusChangedProps) {
  chrome.tabs.query({ active: true, currentWindow: true }, async (tabs) => {
    const currentTab = !isEmpty(tabs) ? tabs[0] : null

    if (
      currentTab &&
      currentTab?.id &&
      currentTab.windowId === currentWindowId
    ) {
      if (callback && currentTab.status === 'complete')
        callback(currentTab as Tab)
    }
  })
}
