import axios, { AxiosInstance } from 'axios'
import { envVariables } from './env'

const { baseURL, timeout, appKey, appVersion } = envVariables

const baseObject = {
  baseURL: baseURL,
  timeout: timeout,
  headers: {
    'X-APP-KEY': appKey,
    'X-APP-VERSION': appVersion,
    'application-source': 'ext',
  },
  withCredentials: true,
}
const pureInstance: AxiosInstance = axios.create(baseObject)
const interceptableInstance: AxiosInstance = axios.create(baseObject)

const fetchBaseObject = {
  baseURL: baseURL,
  timeout: timeout,
  headers: {
    'X-APP-KEY': appKey,
    'X-APP-VERSION': appVersion,
    'application-source': 'ext',
  },
  credentials: 'include',
}
interface FecthInstance {
  url: string
  headers: HeadersInit
  method: string
  body?: BodyInit | null
}
export const fecthInstance = async ({
  url,
  method,
  headers,
  body,
}: FecthInstance) => {
  const controller = new AbortController()
  const timerId = setTimeout(() => controller.abort(), fetchBaseObject.timeout)

  return await fetch(fetchBaseObject.baseURL + url, {
    signal: controller.signal,
    headers: { ...fetchBaseObject.headers, ...headers },
    method,
    body,
    credentials: fetchBaseObject.credentials as RequestCredentials,
  }).then((response) => {
    clearTimeout(timerId)
    return response
  })
}

export const axiosPureInstance = pureInstance
export const axiosInterceptableInstance = interceptableInstance
