import { envVariables } from 'config/env'

const { appKey, appVersion } = envVariables

type HandleRequestProps = {
  url: string
  token?: string
  headers?: any
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'
  body?: any | null
  statusToReject?: number[]
}
export async function handleRequest<T>({
  url,
  headers,
  token,
  body,
  method,
  statusToReject,
}: HandleRequestProps): Promise<T> {
  try {
    const authHeader = token
      ? {
          Authorization: `Bearer ${token}`,
        }
      : {}
    const mountedHeaders = {
      'X-APP-KEY': appKey,
      'X-APP-VERSION': appVersion,
      'application-source': 'ext',
      ...authHeader,
      ...(headers ?? {}),
    }

    const response = await fetch(`${process.env.REACT_APP_API_URL}${url}`, {
      headers: mountedHeaders,
      method: method ?? 'GET',
      body: JSON.stringify(body),
    })

    if (!response.ok) {
      return Promise.reject(new Error(response.statusText))
    }

    if (statusToReject?.includes(response.status)) {
      return Promise.reject(
        new Error(`Enter in status reject list: ${statusToReject.join(', ')}`)
      )
    }

    const responseBody = await response.json()
    return Promise.resolve(responseBody)
  } catch (e: any) {
    return Promise.reject(new Error(`handleRequest error: `, e))
  }
}
