import { removeChromeLocalData } from 'hooks/chrome-storage-change-data'
import { EXTENSION_TOUR_CACHE_NAME } from 'scripts/extension-tour/helper'

export async function showTourListener(sendResponse: (response?: any) => void) {
  removeChromeLocalData(EXTENSION_TOUR_CACHE_NAME)
  return sendResponse(null)
}
