import { CompanyApiResponse } from 'domain/model/company'

interface BinaryFindStoreProps {
  domain: string
  stores: CompanyApiResponse[]
  start: number
  end: number
}
export function binaryFindStore({
  stores,
  start,
  end,
  domain,
}: BinaryFindStoreProps): CompanyApiResponse | null {
  if (start > end) return null

  let mid = Math.floor((start + end) / 2)

  if (stores[mid].url === domain) return stores[mid]

  if (stores[mid].url > domain)
    return binaryFindStore({
      stores,
      start,
      end: mid - 1,
      domain,
    })
  else
    return binaryFindStore({
      stores,
      start: mid + 1,
      end,
      domain,
    })
}
