import { checkIfTabIsPopup } from './check-if-tab-is-popup'

export const TABS_TYPES = {
  CHECK_IF_TAB_IS_POPUP: 'CHECK_IF_TAB_IS_POPUP',
  CHECK_IF_IS_ACTIVE_TAB: 'CHECK_IF_IS_ACTIVE_TAB',
}

export interface CheckIfTabIsPopupResponse {
  isPopup: boolean
}

const listenerTypes: { [key: string]: any } = {
  CHECK_IF_TAB_IS_POPUP: checkIfTabIsPopup,
}

interface Message {
  type: keyof typeof TABS_TYPES
  data: any
}
export const tabsListener =
  (port: chrome.runtime.Port) => async (msg: Message) => {
    if (listenerTypes[msg.type]) return listenerTypes[msg.type](port)

    return port.postMessage({
      status: 400,
      message: 'Invalid tab type',
    })
  }
