import { getProfileService } from 'domain/services/profile/get-profile'
import { CachedProfile, IProfile } from 'hooks/Profile/state'
import { setChromeSyncData } from 'hooks/chrome-storage-change-data'
import { FETCH_PROFILE_TIME, getTimeWithNow } from 'shared/cache'
import { getItemFromSyncCache, setItemFromSyncCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'
import { envVariables } from '../../../config/env'
import { handleRequest } from '../../../utils/handleRequest'
import { getToken } from '../helper/config/common'

export const profileListener =
  (port: chrome.runtime.Port) => async (msg: any) => {
    if (msg.type === 'SET') {
      const cachedProfile = await getItemFromSyncCache<CachedProfile>('profile')
      const tokenResp = await getToken()

      try {
        if (cachedProfile && !isDateExpired(cachedProfile.lastFetch)) {
          return port.postMessage(cachedProfile)
        }

        const profile: any = await handleRequest({
          url: `${envVariables.api.account.profile.path}`,
          token: tokenResp.token,
        })
        const chachedValue: CachedProfile = {
          profile,
          lastFetch: getTimeWithNow(FETCH_PROFILE_TIME),
        }

        await setItemFromSyncCache<CachedProfile>('profile', chachedValue)
      } catch (e: any) {
        console.error({ message: 'ERROR', error: e })
      }
    }

    if (msg.type === 'GET') {
      const cachedProfile = await getItemFromSyncCache<CachedProfile>('profile')
      const tokenResp = await getToken()

      try {
        if (cachedProfile?.profile && !isDateExpired(cachedProfile?.lastFetch))
          return console.info('Profile is cached!')

        const response = await getProfileService<IProfile>(tokenResp?.token)

        if (response) {
          await setChromeSyncData({
            profile: {
              profile: {
                ...response,
              },
              lastFetch: getTimeWithNow(FETCH_PROFILE_TIME),
            },
          })
          return console.info('Fetch profile success!')
        }
      } catch (e) {
        return console.error('Fetch profile unexpected error: ', e)
      }
    }
  }
