import { NOTIFICATION_LOCAL_STORAGE_NAME } from 'shared/notification'
import { light } from 'styles/themes/basic'
import { getCouponsAndOffersQuantity } from './get-coupons-offers-quantity'
import { isValidStoreBackground } from 'domain/services/store/valid-store-background'

const iconURL = chrome.runtime.getURL('icons/pin-32.png')
const imageBlob = fetch(iconURL).then((i) => i.blob())

const imgWidth = 36
const imgHeight = 36
const canvas = new OffscreenCanvas(imgWidth, imgHeight)
const ctx = canvas.getContext('2d', {
  willReadFrequently: true,
}) as OffscreenCanvasRenderingContext2D
let scale = 1
let scaleDirection = 0.2
let animationCounter = 0
let animationTimer: any

async function scaleAnimation() {
  if (animationCounter >= 50 * 61) {
    scale = 1
    animationCounter = 0
    return clearInterval(animationTimer)
  }

  const imageBitmap = await createImageBitmap(await imageBlob)
  ctx.clearRect(0, 0, canvas.width, canvas.height)
  ctx.save()
  ctx.translate(imgWidth * 0.5, imgHeight * 0.5)
  ctx.scale(scale, scale)
  ctx.translate(-imgWidth * 0.5, -imgHeight * 0.5)
  ctx.drawImage(imageBitmap, 0, 0)
  ctx.restore()

  const imageData = ctx.getImageData(0, 0, imgWidth, imgHeight, {})

  chrome.action.setIcon({ imageData })

  animationCounter += 50

  scale += scaleDirection
  if (scale < 0.2 || scale > 1) {
    scaleDirection = -scaleDirection
  } else {
    scaleDirection = +scaleDirection
  }
}

function clearAnimation() {
  clearInterval(animationTimer)
  chrome.action.setIcon({ path: iconURL })
  scale = 1
  scaleDirection = 0.2
  animationCounter = 0
}

export async function makeBadge(tabId: number): Promise<void> {
  clearAnimation()
  const { isValid, shortname } = await isValidStoreBackground()

  const notification = await chrome.storage.local.get([
    NOTIFICATION_LOCAL_STORAGE_NAME,
  ])
  const parsedNotification =
    notification?.[NOTIFICATION_LOCAL_STORAGE_NAME] &&
    JSON.parse(notification?.[NOTIFICATION_LOCAL_STORAGE_NAME])

  const notificationCount = parsedNotification?.count
    ? parsedNotification.count
    : 0

  const couponsAndOffersQuantity = isValid
    ? await getCouponsAndOffersQuantity(shortname)
    : 0

  const count = couponsAndOffersQuantity + notificationCount

  if (animationTimer) {
    clearAnimation()
  }

  animationTimer = !!count && setInterval(scaleAnimation, 50)

  await chrome.action.setBadgeBackgroundColor({ color: light.colors.ra1000 })
  await chrome.action.setBadgeText({ text: `${count ? count : ''}`, tabId })
}
