import {
  Discount,
  DiscountsApiResponse,
  DiscountsSummaryApiResponse,
} from 'domain/model/discounts/main'
import { handleRequest } from 'utils/handleRequest'

export class DiscountsService {
  static async getByShortname(shortname: string) {
    try {
      return await handleRequest<DiscountsApiResponse>({
        url: `/v1/discounts/company/shortname/${shortname}`,
      })
    } catch (_) {
      return null
    }
  }

  static async getRedirectUrl(discountId: string) {
    try {
      return await handleRequest<Discount>({
        url: `/v1/discounts/${discountId}`,
      })
    } catch (_) {
      return null
    }
  }

  static async getSummary() {
    try {
      return await handleRequest<DiscountsSummaryApiResponse[]>({
        url: `/v1/discounts/summary`,
      })
    } catch (_) {
      return null
    }
  }
}
