import { PutExtensionConfigProps } from 'domain/services/profile/put-extension-config'
import { PutExtensionNotificationsConfigProps } from 'domain/services/profile/put-extension-notifications-config'
import { PutExtensionPinConfigProps } from 'domain/services/profile/put-extension-pin-config'
import { updateConfig } from './update-config'
import { updateNotificationsConfig } from './update-notifications-config'
import { updatePingConfig } from './update-pin-config'

export const preferenceTypes = {
  updateConfig: 'UPDATE_CONFIG',
  updatePinConfig: 'UPDATE_PIN_CONFIG',
  updateNotificationsConfig: 'UPDATE_NOTIFICATIONS_CONFIG',
}

interface Message {
  type: 'UPDATE_PIN_CONFIG'
  data: any
}
export const preferencesListener =
  (port: chrome.runtime.Port) => async (msg: Message) => {
    let data
    if (msg.type === preferenceTypes.updatePinConfig) {
      data = await updatePingConfig(msg.data as PutExtensionPinConfigProps)
    }

    if (msg.type === preferenceTypes.updateConfig) {
      data = await updateConfig(msg.data as PutExtensionConfigProps)
    }

    if (msg.type === preferenceTypes.updateNotificationsConfig) {
      data = await updateNotificationsConfig(
        msg.data as PutExtensionNotificationsConfigProps
      )
    }

    if (!data) data = { status: 400, message: 'Invalid update config type' }

    return port.postMessage(data)
  }
