import { CacheDataLastTime } from 'domain/model/background'
import { getItemFromCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'

export interface CacheHelperResponse<T> {
  isExpired: boolean
  data?: CacheDataLastTime<T> | null
}
export async function cacheHelper<T>(
  cacheKey: string
): Promise<CacheHelperResponse<T>> {
  const cachedData = await getItemFromCache<CacheDataLastTime<any>>(cacheKey)

  const isExpired = cachedData && isDateExpired(cachedData?.lastFetch)

  return {
    isExpired,
    data: cachedData,
  }
}
