import { DISCOUNTS_SUMMARY_TIME, getTimeWithNow } from 'shared/cache'
import { getItemFromCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'
import { CacheDataLastTime } from '../model/background'
import { DiscountsService } from './discounts'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'

const DISCOUNTS_SUMMARY_CACHE_NAME = 'discounts_summary'

export const discountsSummaryService = async (): Promise<
  DiscountsSummaryApiResponse[] | null
> => {
  try {
    const parsedData = await getItemFromCache<
      CacheDataLastTime<DiscountsSummaryApiResponse[]>
    >(DISCOUNTS_SUMMARY_CACHE_NAME)

    if (parsedData && !isDateExpired(parsedData.lastFetch))
      return parsedData.data

    const response = await DiscountsService.getSummary()

    if (!response)
      throw new Error(
        `DiscountsSummaryService response is invalid: ${response}`
      )

    await chrome.storage.local.set({
      [DISCOUNTS_SUMMARY_CACHE_NAME]: JSON.stringify({
        data: response,
        lastFetch: getTimeWithNow(DISCOUNTS_SUMMARY_TIME),
      }),
    })

    return response
  } catch (e) {
    console.error('DiscountsSummaryService Unexpected Error: ', e)
    return null
  }
}
