function getCookie(name: string) {
  const value = `; ${document.cookie}`
  const parts = value.split(`; ${name}=`)
  if (parts.length === 2) return parts.pop()?.split(';').shift()
}

function setCookie(name: string, value: any, ttl: number) {
  let expires = ''
  if (ttl) {
    const date = new Date()
    date.setTime(date.getTime() + ttl)
    expires = '; expires=' + date.toUTCString()
  }
  document.cookie = name + '=' + (value || '') + expires + '; path=/'
}

async function chromeGetCookie(url: string, name: string) {
  return await chrome.cookies.get({ url, name })
}

async function chromeSetCookie(url: string, name: string, value: any, ttl: number) {
  const date = new Date()
  let expires = date.getTime()
  if (ttl) {
    expires += ttl
  }
  chrome.cookies.set({ url, name, expirationDate: expires, value })
}

export { getCookie, setCookie, chromeGetCookie, chromeSetCookie }
