import { backgroundApiRequest } from './background-api-request'

type OnUpdatedListener = (
  tabId: number,
  changeInfo: chrome.tabs.TabChangeInfo,
  tab: chrome.tabs.Tab
) => void
export const onUpdatedListener: OnUpdatedListener = async (
  tabId,
  changeInfo,
  _
) => {
  if (changeInfo.status !== 'complete') {
    return false
  }

  if (tabId)
    backgroundApiRequest({
      currentTab: { id: tabId },
      errorOrigin: 'onUpdated',
    })

  return true
}
