export function isString(value: any) {
  return typeof value === 'string'
}

export async function getItemFromCache<T>(
  key: string,
  defaultValue?: T
): Promise<T> {
  const fullCache = await chrome.storage.local.get([key])
  const validCachedValue = fullCache?.[key] || defaultValue || null

  const parsedItem: T = isString(validCachedValue)
    ? JSON.parse(validCachedValue)
    : validCachedValue

  return parsedItem
}

export async function setItemFromCache<T>(
  key: string,
  value: T
): Promise<void> {
  await chrome.storage.local.set({ [key]: value })
}

export async function getItemFromSyncCache<T>(
  key: string,
  defaultValue?: T
): Promise<T> {
  const fullCache = await chrome.storage.sync.get([key])
  const validCachedValue = fullCache?.[key] || defaultValue || null

  const parsedItem: T =
    typeof validCachedValue === 'string'
      ? JSON.parse(validCachedValue)
      : validCachedValue

  return parsedItem
}

export async function setItemFromSyncCache<T>(
  key: string,
  value: T
): Promise<void> {
  await chrome.storage.sync.set({ [key]: value })
}
