import { coordData, dotsCoord } from './coords-helper'

export function makeStepData(stepNumber: string) {
  return {
    imageUrl: `${process.env.REACT_APP_ASSETS_IMAGES_BUCKET_URL}/ra_cupons/extension/newTour/${stepNumber}.svg`,
    mapName: `extension_step_${stepNumber}`,
    dotsCoord: dotsCoord[stepNumber as keyof typeof dotsCoord],
    coords: coordData[stepNumber as keyof typeof coordData],
    nextStep: `/step/${Number(stepNumber) + 1}`,
  }
}

export const EXTENSION_TOUR_CACHE_NAME = 'extension_tour_state'
export const EXTENSION_TOUR_STATES = {
  finished: 'finished',
  skipped: 'skipped',
}
