import { getItemFromCache, setItemFromCache } from 'utils/cacheUtils'
import { backgroundApiRequest } from './background-api-request'
import { tabFocusChanged } from './helpers/tab-focus-changed'
import { getCompanyDiscounts } from 'domain/services/cache-company'
import { removeChromeLocalData } from 'hooks/chrome-storage-change-data'
import { CURRENT_COMPANY_DISCOUNTS } from 'shared/caches/company-discounts'

export const ON_FOCUS_CACHE_NAMES = {
  FOCUSED_WINDOW_ID: 'FOCUSED_WINDOW_ID',
  PREV_FOCUSED_WINDOW_ID: 'PREV_FOCUSED_WINDOW_ID',
  FOCUSED_TAB_URL: 'FOCUSED_TAB_URL',
}

type OnFocusListenerProps = (windowId: number) => void
export const onFocusListener: OnFocusListenerProps = async (
  focusedWindowId
) => {
  await setItemFromCache(
    ON_FOCUS_CACHE_NAMES.FOCUSED_WINDOW_ID,
    focusedWindowId
  )
  const prevFocusedWindowId = await getItemFromCache<number>(
    ON_FOCUS_CACHE_NAMES.PREV_FOCUSED_WINDOW_ID
  )

  const changePopupToOtherPopup =
    focusedWindowId === -1 && prevFocusedWindowId === -1

  if (changePopupToOtherPopup) return

  const changeTabWhenPopupIsOpen =
    focusedWindowId !== prevFocusedWindowId && prevFocusedWindowId === -1

  const storeFromCache = await getCompanyDiscounts()

  if (!storeFromCache) await removeChromeLocalData(CURRENT_COMPANY_DISCOUNTS)

  tabFocusChanged({
    currentWindowId: focusedWindowId,
    callback: (currentTab) => {
      backgroundApiRequest({
        currentTab,
        errorOrigin: 'onFocusChanged',
      })
    },
  })

  await setItemFromCache(
    ON_FOCUS_CACHE_NAMES.PREV_FOCUSED_WINDOW_ID,
    focusedWindowId
  )

  if (changeTabWhenPopupIsOpen) {
    window.close()
  }
}
