import { checkIfUrlIsIP, getRegexUrl } from 'utils/urlRegex'

interface IsUrlOnlyIpProps {
  extractedSubdomainUrl: string
}
export function checkIfUrlIsOnlyIp({
  extractedSubdomainUrl,
}: IsUrlOnlyIpProps) {
  return getRegexUrl.testRule({
    rule: checkIfUrlIsIP(),
    text: extractedSubdomainUrl,
  })
}
