import { getNotifications } from './get-notification'
import { getBanner } from './get-banner'

export const notificationType = {
  getNotification: 'GET_NOTIFICATION',
  getBanner: 'GET_BANNER',
}

interface Message {
  type: string
}

export const notificationsListener = 
  (port: chrome.runtime.Port) => async (msg: Message) => {

    if (msg.type === notificationType.getNotification) {    
      await getNotifications(port)
    }

    if(msg.type === notificationType.getBanner) {
      await getBanner(port)
    }

    return
}
