import { envVariables } from 'config/env'
import { fecthInstance } from 'config/http_client'
import { PutExtensionConfigProps } from 'domain/services/profile/put-extension-config'

export const updateConfig = async ({
  token,
  configId,
  extensionId,
  newConfigStatus,
}: PutExtensionConfigProps) => {
  try {
    if (!token) throw new Error('Invalid token.')

    return await fecthInstance({
      method: envVariables.api.account.configs.method,
      url: envVariables.api.account.configs.path + configId,
      headers: {
        Authorization: `Bearer ${token.access_token}`,
      },
      body: JSON.stringify({
        isChecked: newConfigStatus,
        extension_id: extensionId,
      }),
    }).then((response) => ({
      status: response.status,
      message: response.statusText,
    }))
  } catch (e: any) {
    return {
      status: 400,
      message:
        e?.message ?? 'Ocorreu um erro inexperado! Tente novamente mais tarde.',
    }
  }
}
