import { envVariables } from 'config/env'

type HandleBucketRequestProps = {
  baseUrl: 'monetizacaoFeatureFlags'
  path: string
}
export async function handleBucketRequest<T>({
  baseUrl,
  path,
}: HandleBucketRequestProps): Promise<T> {
  try {
    if (!envVariables?.[baseUrl]) throw new Error('Base URL is invalid')

    const response = await fetch(`${envVariables[baseUrl]}${path}`, {
      method: 'GET',
    })

    if (!response.ok) {
      return Promise.reject(new Error(response.statusText))
    }

    const responseBody = await response.json()
    return Promise.resolve(responseBody)
  } catch (e: any) {
    return Promise.reject(new Error(`handleBucketRequest error: `, e))
  }
}
