import { CacheDataLastTime, IGetCurrentUrl } from 'domain/model/background'
import { CompanyApiResponse } from 'domain/model/company'
import { getItemFromCache } from 'utils/cacheUtils'
import { getBackgroundCurrentUrl } from 'utils/location/get-background-current-url'
import { checkIfUrlIsOnlyIp } from 'utils/location/is-url-only-ip'
import { findStore } from 'utils/storeUrl'

export async function isValidStoreBackground() {
  const {
    extractedSubdomainUrl,
    shortSubdomainExtracted,
    domainWithPath,
    raStoreShortName,
    domain,
  }: IGetCurrentUrl = await getBackgroundCurrentUrl()

  const isUrlOnlyIp = checkIfUrlIsOnlyIp({ extractedSubdomainUrl })

  if (isUrlOnlyIp) console.warn('URL is IP')

  if (raStoreShortName) {
    return {
      isValid: true,
      isRAPage: true,
      store: null,
      shortname: raStoreShortName,
      shortSubdomainExtracted,
    }
  }

  const storeList =
    (await getItemFromCache<CacheDataLastTime<CompanyApiResponse[]>>(
      'stores'
    )) || null

  const findedStore = findStore({
    stores: storeList.data,
    domainWithPath,
    shortSubdomainExtracted,
    domain,
  })

  const isValid = isUrlOnlyIp ? false : !!findedStore

  return {
    isValid,
    isRAPage: false,
    store: findedStore,
    shortname: findedStore?.short_name,
    shortSubdomainExtracted,
  }
}
