import { CompanyApiResponse, CompanyFullUrls } from 'domain/model/company'
import { binaryFindStore } from './binarySearch'

interface ICheckIfStoreIsInBlackList {
  storeByDomain?: CompanyApiResponse | null
}
const checkIfStoreIsInBlackList = ({
  storeByDomain,
}: ICheckIfStoreIsInBlackList): boolean => {
  if (!storeByDomain) return false

  if (storeByDomain?.IsSubdomainBlocked) return true

  return false
}

interface FindStoreByDomainProps {
  stores: CompanyApiResponse[]
  shortSubdomainExtracted: string
  domain: string
}
const findStoreByDomain = ({
  stores,
  shortSubdomainExtracted,
  domain,
}: FindStoreByDomainProps) => {

  let findedStore

  findedStore = binaryFindStore({
    stores,
    start: 0,
    end: stores.length - 1,
    domain: shortSubdomainExtracted,
  })

  if(!findedStore){
    findedStore = binaryFindStore({
      stores,
      start: 0,
      end: stores.length - 1,
      domain,
    })
  }
  
  return findedStore ?? null
}

interface FindStoreByDomainWithPathProps {
  stores?: CompanyFullUrls[] | null
  domainWithPath: string
}
const findStoreByDomainWithPath = ({
  stores,
  domainWithPath,
}: FindStoreByDomainWithPathProps) => {
  const findedStore = stores?.find((store) => store.path === domainWithPath)

  return findedStore ?? null
}

interface IFindStoreByShortSubdomainProps {
  stores?: CompanyFullUrls[] | null
  shortSubdomainExtracted: string
}

const findStoreByShortSubdomain = ({
  stores,
  shortSubdomainExtracted,
}: IFindStoreByShortSubdomainProps) => {
  const findedStore = stores?.find(
    (store) => store.path === shortSubdomainExtracted
  )

  return findedStore ?? null
}

interface FindStore {
  stores: CompanyApiResponse[]
  domainWithPath: string
  shortSubdomainExtracted: string
  domain: string,
}
export const findStore = ({
  stores,
  domainWithPath,
  shortSubdomainExtracted,
  domain,
}: FindStore) => {
  if (!stores || !domainWithPath || !shortSubdomainExtracted) return null

  const storeByDomain = findStoreByDomain({ stores, shortSubdomainExtracted, domain})

  const storeIsInBlackList = checkIfStoreIsInBlackList({ storeByDomain })

  if (storeIsInBlackList) return null

  const storeDomainWithPath = findStoreByDomainWithPath({
    stores: storeByDomain?.fullUrls,
    domainWithPath,
  })

  if (storeDomainWithPath !== null) return storeDomainWithPath

  const storeShortSubdomain = findStoreByShortSubdomain({
    stores: storeByDomain?.fullUrls,
    shortSubdomainExtracted,
  })

  if (storeShortSubdomain !== null) return storeShortSubdomain

  return null
}
