export async function checkIfTabIsPopup(port: chrome.runtime.Port) {
  const activePopupTabs = await chrome.tabs.query({
    active: true,
    windowType: 'popup',
  })

  const hasDomainPopup = activePopupTabs.some(
    (tab) => tab.id === port.sender?.tab?.id
  )
  if (hasDomainPopup) return port.postMessage({ isPopup: true })
  return port.postMessage({ isPopup: false })
}
