import { COMPANY_DISCOUNTS_CACHE_PREFIX } from 'shared/prefix-cache-names'
import { setChromeLocalData } from 'hooks/chrome-storage-change-data'
import { CacheDataLastTime } from 'domain/model/background'
import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { FETCH_COMPANY_DISCOUNTS_TIME, getTimeWithNow } from 'shared/cache'
import {
  CacheHelperResponse,
  cacheHelper,
} from 'domain/services/fetch-company-discounts/helpers/cache'

interface CompanyDiscountsCacheControllerProps {
  shortname: string
}
export async function companyDiscountsCacheController({
  shortname,
}: CompanyDiscountsCacheControllerProps) {
  const cachePath = COMPANY_DISCOUNTS_CACHE_PREFIX + shortname
  let cachedData: CacheHelperResponse<DiscountsApiResponseWithPath> | null =
    null

  async function getCachedData() {
    cachedData = await cacheHelper<DiscountsApiResponseWithPath>(cachePath)
    return cachedData
  }

  function hasCache() {
    const isExpired = cachedData?.isExpired ?? true
    return cachedData && isExpired
  }

  async function sendCachedData(sendResponse: (response?: any) => void) {
    sendResponse(cachedData?.data?.data)
  }

  async function saveDataToCache(data: DiscountsApiResponseWithPath) {
    const cacheData: CacheDataLastTime<DiscountsApiResponseWithPath> = {
      data,
      lastFetch: getTimeWithNow(FETCH_COMPANY_DISCOUNTS_TIME),
    }
    await setChromeLocalData({
      [cachePath]: cacheData,
    })
  }

  return {
    getCachedData,
    hasCache,
    sendCachedData,
    saveDataToCache,
  }
}
