import { handleRequest } from 'utils/handleRequest'
import { MessageData } from '../../requestsRules'
import { companyDiscountsCacheController } from './controllers/company-discounts-cache-controller'
import {
  DiscountsApiResponse,
  DiscountsApiResponseWithPath,
} from 'domain/model/discounts/main'

export const getCompanyDiscountsListener = async (
  sendResponse: (response?: any) => void,
  { shortname }: MessageData
) => {
  try {
    if (!shortname) throw new Error('Shortname is required')

    const controller = await companyDiscountsCacheController({ shortname })
    await controller.getCachedData()

    if (!controller.hasCache())
      return await controller.sendCachedData(sendResponse)

    const data = await handleRequest<DiscountsApiResponse>({
      url: `/v1/discounts/company/shortname/${shortname}`,
    })

    if (data) {
      const completeData: DiscountsApiResponseWithPath = {
        ...data,
        path: data.company_info.url,
        ra_path: data.company_info.ra_company_url,
      }

      await controller.saveDataToCache(completeData)

      return sendResponse(completeData)
    }
  } catch (e) {
    console.error('GET COMPANY DISCOUNTS LISTENER - ', JSON.stringify(e))
    return sendResponse(null)
  }

  return sendResponse(null)
}
