import { Tab } from 'domain/model/tab'
import { handleBackgroundApi } from 'domain/services/background'
import { getSiteIsTrust } from 'domain/services/site-detector'
import { getAllStores } from 'domain/services/store/all-stores'
import { makeBadge } from 'scripts/badge/make-badge'

interface BackgroundApiRequestProps {
  currentTab: Tab
  errorOrigin: 'onFocusChanged' | 'onUpdated' | 'onActivated'
}
export const backgroundApiRequest = ({
  currentTab,
  errorOrigin,
}: BackgroundApiRequestProps) => {
  getAllStores()
    .then(() => {
      handleBackgroundApi(currentTab)
        .then(() => {
          makeBadge(currentTab.id)
          // TODO: removendo temporariamente o detector de sites
          // getSiteIsTrust()
        })
        .catch((e) => {
          console.error(`Got error processing in ${errorOrigin}`, e)
        })
    })
    .catch((e) => {
      console.error(`Error getting all stores in ${errorOrigin}`, e)
    })
}
