import {
  getChromeLocalData,
  setChromeLocalData,
} from 'hooks/chrome-storage-change-data'
import { extractExpireTime } from 'utils/auth-token'

interface IConnectionsRules {
  [key: string]: (port: chrome.runtime.Port, msg: any) => void
}
export const requestsRules: IConnectionsRules = {
  CHECK_EXTENSION_AUTH: async function (port) {
    const storage = await getChromeLocalData('checkAuthState')

    if (storage?.checkAuthState) {
      port.postMessage(storage?.checkAuthState)
    }

    chrome.storage.onChanged.addListener((response, areaName) => {
      if (areaName === 'local' && response?.checkAuthState) {
        port.postMessage(response?.checkAuthState?.newValue)
      }
    })
  },
  POST_TOKEN: async function (port, msg) {
    if (!msg?.data)
      return port.postMessage({ status: 400, message: 'Dados inválidos!' })
    if (!msg?.data?.access_token)
      return port.postMessage({ status: 400, message: 'Token inválido!' })

    const expireIn = extractExpireTime(msg?.data?.access_token)

    await setChromeLocalData({
      token: JSON.stringify({
        access_token: msg?.data?.access_token,
        expire_in: expireIn,
      }),
    })

    port.postMessage({ status: 200, message: 'Login efetuado com sucesso' })
  },
}
