import { CacheDataLastTime } from 'domain/model/background'
import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { COMPANY_DISCOUNTS_CACHE_PREFIX } from 'shared/prefix-cache-names'
import { getItemFromCache } from 'utils/cacheUtils'

export const getCouponsAndOffersQuantity = async (shortname?: string) => {
  if (!shortname) return 0

  const cacheUrl = COMPANY_DISCOUNTS_CACHE_PREFIX + shortname

  const cacheData: CacheDataLastTime<DiscountsApiResponseWithPath> =
    await getItemFromCache<any>(cacheUrl)

  const couponsQuantity = cacheData.data.discount_coupons.length ?? 0
  const offersQuantity = cacheData.data.discount_offers.length ?? 0

  return couponsQuantity + offersQuantity
}
