import { envVariables } from 'config/env'
import { CacheDataLastTime } from 'domain/model/background'
import { IToken } from 'hooks/auth/state'
import { NOTIFICATION_CACHE_TIME, getTimeWithNow } from 'shared/cache'
import { NOTIFICATION_LOCAL_STORAGE_NAME } from 'shared/notification'
import { getItemFromCache, setItemFromCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'

export const getNotifications = async (port: chrome.runtime.Port) => {
  const parsedToken = await getItemFromCache<IToken>('token')

  if (!parsedToken) {
    const resp: any[] = []
    await setItemFromCache(NOTIFICATION_LOCAL_STORAGE_NAME, JSON.stringify(resp))
    return resp
  }
  
  const notificationsCache = await getItemFromCache<CacheDataLastTime<Notification[]>>(NOTIFICATION_LOCAL_STORAGE_NAME) 

  if(notificationsCache && !isDateExpired(notificationsCache.lastFetch)){
    port.postMessage(notificationsCache.data)
  }

  await fetch(`${process.env.REACT_APP_API_URL}${envVariables.api.notifications.get.path}`, {
    headers: {
      Authorization: `Bearer ${parsedToken.access_token}`,
    },
  })
    .then((res) => res.json())
    .then(async data => {
      const resp = data?.data || []
      const cacheData: CacheDataLastTime<Notification[]> = {
        data: resp,
        lastFetch: getTimeWithNow(NOTIFICATION_CACHE_TIME)
      }

      await setItemFromCache(NOTIFICATION_LOCAL_STORAGE_NAME, JSON.stringify(cacheData))
      
      port.postMessage(resp)
    })
    .catch(async (_) => {
      const resp: any[] = []
      await setItemFromCache(NOTIFICATION_LOCAL_STORAGE_NAME, JSON.stringify(resp))
      port.postMessage(resp)
    })
}
