export function convertDaysToMillies(value: number) {
  return value * 24 * 60 * 60 * 1000
}

export function convertHoursToMillies(value: number) {
  return value * 60 * 60 * 1000
}

export function convertMinutesToMillies(value: number) {
  return value * 60 * 1000
}

export function convertSecondsToMillies(value: number) {
  return value * 1000
}
