interface IExecRule {
  rule: RegExp
  url: string
  index?: number
}

interface ITestRule {
  rule: RegExp
  text: string
}

export const getRegexUrl = {
  execRule: ({ rule, url, index = 1 }: IExecRule) =>
    rule.exec(url)?.[index] ?? '',
  replaceRule: (rule: RegExp, url: string) => url.replace(rule, ''),
  testRule: ({ rule, text }: ITestRule) => rule.test(text),
}

export const validUrl = () =>
  new RegExp(
    /[(http(s)?)://(www.)?a-zA-Z0-9@:%._+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_+.~#?&//=]*)/gi
  )

export const domainRule = () => 
    new RegExp(/((?<=[a-z0-9\-_~]+[.]|\/\/)([\D]+?)([a-z0-9]{1,4}[.]?){1,2})$/)

export const subdomainRule = () =>
  new RegExp(/^(?:https?:\/\/)?(?:[^@/\n]+@)?(?:www\.)?([^:/?\n]+)/)

export const shortSubdomainExtractedRule = () =>
  new RegExp(/(([a-z0-9\-_~]+[.]?){1}([\D]+?)([a-z0-9]{1,4}[.]?){1,2})$/)

export const domainWithPathPart1Rule = () =>
  new RegExp(/^(http(s)?:\/\/)?(([/\w.-])+)[^/?]/gi)

export const domainWithPathRule = () => new RegExp(/(http(s)?:\/\/(www\.)?)/gi)

export const raStoreShortNameRule = () =>
  new RegExp(/^https:\/\/www\.reclameaqui\.com\.br\/empresa\/(.*)+/)

export const checkIfUrlIsIP = () => new RegExp(/^\d+(\.\d+)*$/)
