import { onActivatedListener } from './background-listeners/on-activated-listener'
import { onFocusListener } from './background-listeners/on-focus-listener'
import { onInstalledListener } from './background-listeners/on-installed-listener'
import { onUpdatedListener } from './background-listeners/on-updated-listener'
import { requests as externalRequests } from './external-message/requests'
import { requests as longLiveExternalRequests } from './long-live-external-message/requests'
import { connections } from './long-live-message/connections'
import { requests } from './short-live-message/requests'

chrome.windows.onFocusChanged.addListener(onFocusListener)

chrome.tabs.onUpdated.addListener(onUpdatedListener)

chrome.tabs.onActivated.addListener(onActivatedListener)

chrome.runtime.onInstalled.addListener(onInstalledListener)

chrome.runtime.setUninstallURL(process.env.REACT_APP_UNINSTALL_URL as string)

chrome.runtime.onConnect.addListener(connections)

chrome.runtime.onMessage.addListener(requests)

chrome.runtime.onMessageExternal.addListener(externalRequests)

chrome.runtime.onConnectExternal.addListener(longLiveExternalRequests)

export {}
