import { IGetCurrentUrl } from 'domain/model/background'
import { isAvailableToIntercept } from 'utils/location/is-available-to-intercept'
import {
  domainRule,
  domainWithPathPart1Rule,
  domainWithPathRule,
  getRegexUrl,
  raStoreShortNameRule,
  shortSubdomainExtractedRule,
  subdomainRule,
} from 'utils/urlRegex'

export const getBackgroundCurrentUrl = async (): Promise<IGetCurrentUrl> => {
  try {
    const tabs = await chrome.tabs.query({
      active: true,
      currentWindow: true,
    })
    const result = {
      domain: '',
      extractedSubdomainUrl: '',
      shortSubdomainExtracted: '',
      fullUrl: '',
      domainWithPath: '',
      raStoreShortName: '',
    }

    if (!tabs[0]?.url) {
      return result
    }

    const rawUrl = tabs[0].url

    const raStoreShortNameWithRoutes = getRegexUrl.execRule({
      rule: raStoreShortNameRule(),
      url: rawUrl,
    })

    const raStoreShortName = raStoreShortNameWithRoutes.split('/')[0] ?? ''

    if (raStoreShortName) {
      return {
        domain: '',
        extractedSubdomainUrl: '',
        shortSubdomainExtracted: '',
        fullUrl: '',
        domainWithPath: '',
        raStoreShortName,
      }
    }

    if (!isAvailableToIntercept(rawUrl)) {
      return result
    }
    
    

    const extractedSubdomainUrl = getRegexUrl.execRule({
      rule: subdomainRule(),
      url: rawUrl,
    })

    const shortSubdomainExtracted = getRegexUrl.execRule({
      rule: shortSubdomainExtractedRule(),
      url: extractedSubdomainUrl,
    })

    const domain = getRegexUrl.execRule({
      rule: domainRule(),
      url: shortSubdomainExtracted,
    })

    const domainWithPathPart1 = getRegexUrl.execRule({
      rule: domainWithPathPart1Rule(),
      url: rawUrl,
      index: 0,
    })

    const domainWithPath = getRegexUrl.replaceRule(
      domainWithPathRule(),
      domainWithPathPart1
    )

    return {
      domain,
      extractedSubdomainUrl,
      shortSubdomainExtracted,
      fullUrl: rawUrl,
      domainWithPath,
      raStoreShortName,
    }
  } catch (err) {
    return Promise.reject(err)
  }
}
