import { clearStorage } from 'domain/services/extension-version'

type OnInstalledListener = (details: chrome.runtime.InstalledDetails) => void
export const onInstalledListener: OnInstalledListener = ({ reason }) => {
  clearStorage().finally(() => {
    if (reason === 'install') {
      const redirectUri = process.env.REACT_APP_REDIRECT_URL as string

      chrome.tabs.create({
        url: redirectUri,
      })
    }
  })
}
