import { PIN_LOCALIZATION } from 'scripts/pin-component/shared/pinState'

export const clearStorage = async () => {
  try {
    let localStoragePinLocalization = localStorage.getItem(PIN_LOCALIZATION)
    await chrome.storage.local.clear()
    localStorage.setItem(PIN_LOCALIZATION, localStoragePinLocalization || '')
  } catch (e) {
    console.error('Error when clear cache: ', e)
  }
}
