import { handleRequest } from 'utils/handleRequest'
import { CompanyFullUrls } from 'domain/model/company'
import { DiscountsApiResponse } from 'domain/model/discounts/main'
import {
  clearCache,
  companyDiscountsCacheController,
} from './controllers/company-discounts-cache-controller'

interface FetchCompanyDiscountsPros {
  store: CompanyFullUrls | null
  shortname?: string
  isRAPage?: boolean
}
export async function fetchCompanyDiscounts({
  store,
  shortname,
  isRAPage,
}: FetchCompanyDiscountsPros) {
  try {
    if (!shortname)
      throw new Error('Ra Shortname or Company Shortname is empty!')

    const controller = await companyDiscountsCacheController({ shortname })
    await controller.getCachedData()

    if (!controller.needFetchData()) return await controller.useCachedData()

    return handleRequest<DiscountsApiResponse>({
      url: `/v1/discounts/company/shortname/${shortname}`,
    })
      .then(async (companyDiscounts) => {
        await controller.saveDataToCache({
          ...companyDiscounts,
          path: companyDiscounts.company_info.url,
          ra_path: companyDiscounts.company_info.ra_company_url,
        })
      })
      .catch(async () => {
        await clearCache()
      })
  } catch (e) {
    await clearCache()
    console.error('Error fetching company discounts - ', JSON.stringify(e))
  }
}
