import { COMPANY_DISCOUNTS_CACHE_PREFIX } from 'shared/prefix-cache-names'
import { getItemFromCache } from 'utils/cacheUtils'
import { findStore } from 'utils/storeUrl'
import { getBackgroundCurrentUrl } from '../../utils/location/get-background-current-url'
import { CacheDataLastTime } from '../model/background'
import { CompanyApiResponse, CompanyFullUrls } from 'domain/model/company'
import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'

async function getCompanyFromList(): Promise<CompanyFullUrls | null> {
  const { domainWithPath, shortSubdomainExtracted, raStoreShortName, domain } =
    await getBackgroundCurrentUrl()

  if (raStoreShortName)
    return {
      id: '',
      name: '',
      path: '',
      short_name: raStoreShortName,
    }

  const storeList =
    (await getItemFromCache<CacheDataLastTime<CompanyApiResponse[]>>(
      'stores'
    )) || {}

  if (!storeList?.data) {
    return null
  }

  const store = findStore({
    stores: storeList.data,
    domainWithPath,
    shortSubdomainExtracted,
    domain,
  })

  if (store === null) return null

  return store
}

export async function getCachedCompany(
  shortname: string
): Promise<CacheDataLastTime<DiscountsApiResponseWithPath> | null> {
  const storeCached = await getItemFromCache<
    CacheDataLastTime<DiscountsApiResponseWithPath>
  >(COMPANY_DISCOUNTS_CACHE_PREFIX + shortname)

  return storeCached ? storeCached : null
}

interface FindedStoreWithCachedStore {
  store: CompanyFullUrls
  storeCached: CacheDataLastTime<DiscountsApiResponseWithPath> | null
}
export async function getCompanyDiscounts(): Promise<FindedStoreWithCachedStore | null> {
  try {
    const storeFromList = await getCompanyFromList()

    if (storeFromList === null) return null

    const cachedStore = await getCachedCompany(storeFromList.short_name)

    return {
      store: storeFromList,
      storeCached: cachedStore,
    }
  } catch (e) {
    return null
  }
}

export async function getCurrentCompanyDiscountsInCache() {
  const storeFromCache = await getCompanyDiscounts()
  if (!storeFromCache) return

  const { storeCached } = storeFromCache

  if (!storeCached) return

  return storeCached.data
}
