import { CacheDataLastTime } from 'domain/model/background'
import { IToken } from 'hooks/auth/state'
import { Banner } from 'scripts/pin-component/hooks/notifications/state'
import { BANNER_NOTIFICATION_CACHE_TIME, getTimeWithNow } from 'shared/cache'
import { BANNERS_LOCAL_STORAGE_NAME } from 'shared/notification'
import { getItemFromCache, setItemFromCache } from 'utils/cacheUtils'
import { isDateExpired } from 'utils/dateHelper'


export const getBanner = async (port: chrome.runtime.Port) => {
    const parsedToken = await getItemFromCache<IToken>('token')

    if (!parsedToken) {
      const resp: any[] = []
      await setItemFromCache(BANNERS_LOCAL_STORAGE_NAME, JSON.stringify(resp))
      return port.postMessage(resp)
    }
    
    const bannerCache = await getItemFromCache<CacheDataLastTime<Banner[]>>(BANNERS_LOCAL_STORAGE_NAME) 

    if(bannerCache && !isDateExpired(bannerCache.lastFetch)){
      port.postMessage(bannerCache.data)
    }

    await fetch(`${process.env.REACT_APP_API_URL}/banners`, {
      headers: {
        Authorization: `Bearer ${parsedToken?.access_token}`,
      },
    })
      .then((res) => res.json())
      .then(async data => {
        const cacheData: CacheDataLastTime<Banner[]> = {
          data: data,
          lastFetch: getTimeWithNow(BANNER_NOTIFICATION_CACHE_TIME)
        }


        await setItemFromCache(BANNERS_LOCAL_STORAGE_NAME, JSON.stringify(cacheData))
        port.postMessage(data)
      })
      .catch(async (_) => {
        const resp: {} = {}
        await setItemFromCache(BANNERS_LOCAL_STORAGE_NAME, JSON.stringify(resp))
      port.postMessage(resp)
      })
}
