import { askCookieListener } from './listener-rules/ask-cookie-listener'
import { notificationsListener } from './listener-rules/notifications/notifications-listener'
import { preferencesListener } from './listener-rules/preferences/preferences-listener'
import { profileListener } from './listener-rules/profile-listener'
import { ravConfigListenerListener } from './listener-rules/rav-config-listener/get-listener'
import { sendEventListener } from './listener-rules/send-event/send-event-listener'
import { tabsListener } from './listener-rules/tabs-listener'

interface IConnectionsRules {
  [key: string]: (port: chrome.runtime.Port) => void
}

export const connectionsRules: IConnectionsRules = {
  NOTIFICATIONS: async (port) => {
    port.onMessage.addListener(notificationsListener(port))
  },
  ASK_COOKIE(port) {
    port.onMessage.addListener(askCookieListener(port))
  },
  PROFILE: async (port) => {
    port.onMessage.addListener(profileListener(port))
  },
  PREFERENCES: async (port) => {
    port.onMessage.addListener(preferencesListener(port))
  },
  TABS: async (port) => {
    port.onMessage.addListener(tabsListener(port))
  },
  RAV_CONFIG: async (port) => {
    port.onMessage.addListener(ravConfigListenerListener(port))
  },
  SEND_EVENT: async function (port) {
    port.onMessage.addListener(sendEventListener)
  },
}
