import { envVariables } from 'config/env'
import { fecthInstance } from 'config/http_client'
import { PutExtensionPinConfigProps } from 'domain/services/profile/put-extension-pin-config'

export const updatePingConfig = async ({
  token,
  paramName,
  value,
}: PutExtensionPinConfigProps) => {
  try {
    if (!token) throw new Error('Invalid token.')

    return await fecthInstance({
      method: envVariables.api.account.pinConfigs.method,
      url: envVariables.api.account.pinConfigs.path,
      headers: {
        Authorization: `Bearer ${token.access_token}`,
      },
      body: JSON.stringify({ [paramName]: value }),
    }).then((response) => ({
      status: response.status,
      message: response.statusText,
    }))
  } catch (e: any) {
    return {
      status: 400,
      message:
        e?.message ?? 'Ocorreu um erro inexperado! Tente novamente mais tarde.',
    }
  }
}
