import { envVariables } from 'config/env'
import { fecthInstance } from 'config/http_client'

export async function getProfileService<T>(
  token?: string
): Promise<T | undefined> {
  try {
    if (!token) throw new Error('Invalid token.')

    const response = await fecthInstance({
      method: envVariables.api.account.profile.method,
      url: envVariables.api.account.profile.path,
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })

    if (response.ok) {
      const data = await response.json()
      return data as T
    }
    return undefined
  } catch (e) {
    console.error(`GET PROFILE: ${e}`)
  }
}
