import { StorageArea } from 'domain/model/chrome-storage'

async function getChromeData(storageArea: StorageArea, key: string) {
  return await chrome.storage[storageArea].get(key)
}

async function setChromeData(storageArea: StorageArea, data: object) {
  return await chrome.storage[storageArea].set(data)
}

async function removeChromeData(
  storageArea: StorageArea,
  key: string | string[]
) {
  return await chrome.storage[storageArea].remove(key)
}

export async function getChromeLocalData(key: string) {
  return await getChromeData('local', key)
}

export async function getChromeSyncData(key: string) {
  return await getChromeData('sync', key)
}

export async function setChromeLocalData(data: object) {
  return await setChromeData('local', data)
}

export async function setChromeSyncData(data: object) {
  return await setChromeData('sync', data)
}

export async function removeChromeLocalData(key: string | string[]) {
  return await removeChromeData('local', key)
}

export async function removeChromeSyncData(key: string | string[]) {
  return await removeChromeData('sync', key)
}
