import { RavConfig } from 'domain/model/rav-config'
import { handleBucketRequest } from 'utils/handleBucketRequest'

export const getRavConfig: () => Promise<RavConfig | undefined> = async () => {
  try {
    return await handleBucketRequest<RavConfig | undefined>({
      baseUrl: 'monetizacaoFeatureFlags',
      path: '/rav-config.json',
    })
  } catch (e: any) {
    console.error('GET RavConfig: ', e.message)
    return undefined
  }
}
