import { chromeGetCookie, chromeSetCookie } from '../../../utils/cookiesHelper'
export const askCookieListener =  (port: chrome.runtime.Port) => async (msg: any) => {
  const ASK_MODAL_URL_COOKIE = 'https://mais.reclameaqui.com.br/'
  const LAST_SESSION_ASK_MODAL_NAME = 'ramais_lastTime_session_ask_modal'
  const SHOW_INTERVAL = 12 * 60 * 60 * 1000

  if (msg.type === 'GET') {
    const askCookie = await chromeGetCookie(ASK_MODAL_URL_COOKIE, LAST_SESSION_ASK_MODAL_NAME)

    if(!askCookie)
      return port.postMessage(null)
    
    return port.postMessage(askCookie)
  }

  if (msg.type === 'SET') {
    chromeSetCookie(
      ASK_MODAL_URL_COOKIE,
      LAST_SESSION_ASK_MODAL_NAME,
      `${Date.now().toString()}/${++msg.count}`,
      SHOW_INTERVAL
    )
  }
}